import { readdirSync, readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { NpcsServerPacketId as NS, SpellClientPacketId as SC, SpellServerPacketId as SS, decodeClientPacket, decodeServerPacket, encodeClientPacket, encodeServerPacket } from '../src/index.js';

// Recordings of the real classic VB6 server (tests/fixtures/vb6/spells). Never regenerated by tests.
const dir = new URL('../../../tests/fixtures/vb6/spells/', import.meta.url);
interface Line { t_ms: number; dir: 'c2s' | 's2c'; id: number; name: string; hex: string }
const recordings = readdirSync(dir).filter(name => name.endsWith('.jsonl')).map(name => ({
  name, lines: readFileSync(new URL(name, dir), 'utf8').trim().split('\n').map(line => JSON.parse(line) as Line),
}));
const bytes = (hex: string) => Uint8Array.from(Buffer.from(hex, 'hex'));
const hex = (value: Uint8Array) => Buffer.from(value).toString('hex');
const find = (id: number, dirName: Line['dir']) => recordings.flatMap(r => r.lines).filter(l => l.id === id && l.dir === dirName);

describe('spell packets against real VB6 recordings', () => {
  it('has recordings for every spell sub-feature', () => {
    expect(recordings.map(r => r.name).sort()).toEqual(['cast-invalid-target.jsonl', 'cast-orb.jsonl', 'cast-self.jsonl', 'cast-summon.jsonl', 'dardo-magico-kills-creature.jsonl', 'dardo-magico-training-dummy.jsonl']);
  });
  for (const recording of recordings) {
    it(`${recording.name}: every owned packet decodes and re-encodes to the same bytes`, () => {
      const ownedBy = { s2c: new Set<number>(Object.values(SS).filter(v => typeof v === 'number')), c2s: new Set<number>(Object.values(SC).filter(v => typeof v === 'number')) };
      let checked = 0;
      for (const line of recording.lines.filter(l => ownedBy[l.dir].has(l.id))) {
        const body = bytes(line.hex);
        if (line.dir === 's2c') { const p = decodeServerPacket(body); expect('unknown' in p).toBe(false); expect(hex(encodeServerPacket(p as never))).toBe(line.hex); }
        else { const p = decodeClientPacket(body); expect('unknown' in p).toBe(false); expect(hex(encodeClientPacket(p as never))).toBe(line.hex); }
        checked++;
      }
      expect(checked).toBeGreaterThan(0);
    });
  }
  it('decodes the recorded golden values', () => {
    expect(decodeServerPacket(bytes(find(SS.WorkRequestTarget, 's2c')[0]!.hex))).toEqual({ id: SS.WorkRequestTarget, skill: 1, area: false, radius: 0 });
    expect(decodeClientPacket(bytes(find(SC.CastSpell, 'c2s')[0]!.hex))).toEqual({ id: SC.CastSpell, slot: 1, counter: 1 });
    expect(decodeClientPacket(bytes(find(SC.WorkLeftClick, 'c2s')[0]!.hex))).toMatchObject({ id: SC.WorkLeftClick, skill: 1, counter: 1 });
    expect(decodeClientPacket(bytes(find(SC.SpellInfo, 'c2s')[0]!.hex))).toEqual({ id: SC.SpellInfo, slot: 1 });
    expect(decodeClientPacket(bytes(find(SC.MoveSpell, 'c2s')[0]!.hex))).toEqual({ id: SC.MoveSpell, up: false, slot: 1 });
    const targetInvalid = find(NS.LocaleMsg, 's2c').map(l => decodeServerPacket(bytes(l.hex))).filter(p => p.id === NS.LocaleMsg); // npcs codec
    expect(targetInvalid).toContainEqual({ id: NS.LocaleMsg, messageId: 792, text: '', font: 32, channel: 1 });
    expect(targetInvalid).toContainEqual({ id: NS.LocaleMsg, messageId: 380, text: '', font: 1, channel: 1 });
    expect(find(SS.CreateFX, 's2c').length).toBeGreaterThan(0);
  });
  it('round-trips hand-built layouts for packets the recordings did not trigger', () => {
    const cases = [
      { id: SS.FxFloor, x: 51, y: 60, grh: 20 }, { id: SS.PlayWave, wave: 403, x: 57, y: 44, cancelLast: 0, localize: 0 },
      { id: SS.ParticleFX, charIndex: 5, particle: 12, time: 20, remove: true, grh: 0, x: 0, y: 0 },
      { id: SS.ParticleFXToFloor, x: 1, y: 2, particle: 3, time: 4 },
      { id: SS.ParticleFXWithDestino, sender: 1, receiver: 2, travelParticle: 186, finalParticle: 7, time: 9, wave: 16, fx: 15, x: 3, y: 4 },
      { id: SS.ParticleFXWithDestinoXY, sender: 1, travelParticle: 186, finalParticle: 7, time: 9, wave: 16, fx: 15, x: 3, y: 4 },
      { id: SS.SendSkillCdUpdate, typeId: 4, skillId: -1, timeLeft: 1000, totalTime: 2000, effectType: 2, stacks: 1 },
      { id: SS.NotifyCasting, value: 1 }, { id: SS.CreateProjectile, startX: 1, startY: 2, targetX: 3, targetY: 4, projectileType: 1 },
      { id: NS.LocaleMsg, messageId: 8, text: 'ñ¬1', font: 7 },
    ] as const;
    for (const packet of cases) expect(decodeServerPacket(encodeServerPacket(packet as never))).toEqual(packet);
  });
  // #19 item 1: hex written by hand from the VB6 field order (server Protocol_Writes.bas Prepare*/Write*), little endian, NOT produced by the codec.
  it('NotifyInventarioHechizos (client 293) is Int8 x3: value, selected row, scroll', () => {
    expect(hex(encodeClientPacket({ id: SC.NotifyInventarioHechizos, value: 2, hechiSel: 3, scrollSel: 1 }))).toBe('25010203' + '01');
  });
  it('matches hand-derived hex for 51, 60, 114, 115, 116, 180, 185 and 191', () => {
    const golden: [object, string][] = [
      [{ id: SS.FxFloor, x: 51, y: 60, grh: 20 }, '3300333c1400'],
      [{ id: SS.CreateFX, charIndex: 5, fx: 15, loops: 2, x: 7, y: 8 }, '3c0005000f0002000708'],
      [{ id: SS.ParticleFXToFloor, x: 1, y: 2, particle: 3, time: 4 }, '72000102030004000000'],
      [{ id: SS.ParticleFXWithDestino, sender: 1, receiver: 2, travelParticle: 186, finalParticle: 7, time: 9, wave: 16, fx: 15, x: 3, y: 4 }, '7300' + '0100' + '0200' + 'ba00' + '0700' + '09000000' + '1000' + '0f00' + '0304'],
      [{ id: SS.ParticleFXWithDestinoXY, sender: 1, travelParticle: 186, finalParticle: 7, time: 9, wave: 16, fx: 15, x: 3, y: 4 }, '7400' + '0100' + 'ba00' + '0700' + '09000000' + '1000' + '0f00' + '0304'],
      [{ id: SS.SendSkillCdUpdate, typeId: 4, skillId: -1, timeLeft: 1000, totalTime: 2000, effectType: 2, stacks: 1 }, 'b4000400ffffffffe8030000d0070000020100'],
      [{ id: SS.NotifyCasting, value: 1 }, 'b90001'],
      [{ id: SS.GetInventarioHechizos, value: 2, hechiSel: 3, scrollSel: 1 }, 'b8000203' + '01'],
      [{ id: SS.CreateProjectile, startX: 1, startY: 2, targetX: 3, targetY: 4, projectileType: 1 }, 'bf00' + '0102030401'],
    ];
    for (const [packet, expected] of golden) {
      expect(hex(encodeServerPacket(packet as never))).toBe(expected);
      expect(decodeServerPacket(bytes(expected))).toEqual(packet);
    }
  });
});
